namespace WOMENACE.Code;

internal static partial class SpringBodyProfiles
{
    // Generated by scripts/pmx_to_menace.py from the PMX's physics bodies
    // (nemesis/default). Tune it in place: the converter never rewrites it.
    internal static readonly SpringBodyProfile NemesisDefault = new()
    {
        LodMesh = "nemesis_LOD0",
        Chains = new[]
        {
            SpringPresets.ShortHair(
                "HairC1>HairC3",
                "HairD1>HairD3",
                "HairF1>HairF3"
            ),
            NemesisLongHair(
                "HairA1>HairA25",
                "HairB1>HairB25",
                "HairE2>HairE11"
            ),
            SpringPresets.StiffCloth(
                "Earring_L01>Earring_L02",
                "Earring_R01>Earring_R02"
            ),
            NemesisCloak(
                "CapeL1>CapeL11",
                "CapeR1>CapeR11"
            ),
        },
        Colliders = HumanoidColliders(1.678f),
    };

    // Her hair runs to below the hips (twenty-five bones on this outfit). At the preset's
    // light gravity and soft stiffness it drifts and lingers after every turn, so it hangs
    // heavier and returns faster on all three outfits.
    internal static SpringChainSpec NemesisLongHair(params string[] roots)
    {
        var spec = SpringPresets.LongHair(roots);
        spec.Gravity = 0.7f;
        spec.Stiffness = 4f;
        spec.Drag = 0.4f;
        return spec;
    }

    // The shawl ends that hang to her knees: heavier and firmer than the skirt preset, which
    // floated after every turn.
    internal static SpringChainSpec NemesisCloak(params string[] roots)
    {
        var spec = SpringPresets.Skirt(roots);
        spec.Gravity = 1f;
        spec.Stiffness = 2.5f;
        spec.TipStiffness = 2f;
        spec.Drag = 0.5f;
        return spec;
    }
}
